// One-bit Karnaugh map function. Implemented as a SOP (sum-of-products)
// expression, which is more efficient than a POS (product-of-sums) one.
// (see https://en.wikipedia.org/wiki/Karnaugh_map#POL_and_SOP)
function [0:0] f_kmap_1bit (input a, b, c);
    reg [0:0] out;
    out = ~(~a & ~b & ~c) & ~(~a & ~b & c) & ~(~a & c & ~b) & ~(~a & c & b) &
          ~(a & ~b & ~c) & ~(a & ~b & c) & ~(a & c & ~b) & ~(a & c & b);
    return out;
endfunction

// Top-level module. Instantiates the one-bit Karnaugh map function and
// inverts the output to match the desired function.
module TopModule (input a, b, c, output out);
    wire [0:0] fn_out = f_kmap_1bit(a, b, c);
    assign out = ~fn_out;
endmodule

